guard let methods = container.methods else {
      continue
    }
    for method in methods {
      if let signature = method.swiftSignature {
        if let body = method.body {
          // We have the original source for the body.
          let bodyLines = formatBodyAsComment(body)
          let bodyText = bodyLines.joined(separator: "\n        ")
          if signature.contains(idePlaceholder) {
            // The compiler attached a stub body to the signature.
            var stub = signature.replacingOccurrences(of: idePlaceholder, with: bodyText)
            output.append(stub)
          } else {
            // The compiler returned a signature with no body.
            output.append(signature.dropLast() + " {")
            output.append("        " + bodyText)
            output.append("    }")
          }
        } else {
          output.append(signature.dropLast() + " {")
          output.append("    }")
        }
      }
    }

