export function getMDXComponents(components?: MDXComponents): MDXComponents {
  return {
    ...defaultMdxComponents,
    ...TabsComponents,
    AlertTriangle,
    Callout,
    Card,
    Cards,
    CheckCircle,
    CodeBlock,
    CollapsibleCode,
    ComponentCard,
    ComponentCount,
    ComponentGrid,
    ComponentPreview: ComponentPreviewWithSuspense,
    ComponentsCategory,
    CopyPrompt,
    DocsImage,
    ExampleCount,
    Icon,
    Info,
    Link: LocaleLink,
    NativeComponentsCategory,
    NativeImageHeroView,
    NativeQRPreviewPopover,
    NativeTryOnDevice,
    NativeVideoPlayerView,
    NewsletterForm,
    PackageManagers,
    Pre,
    Preview,
    RelatedComponents,
    RelatedShowcases,
    Star,
    VideoPlayer,
    X,
    XCircle,
    // HTML `ref` attribute conflicts with `forwardRef`
    pre: ({children, ref: _ref, ...props}) => {
      // Check if the code has more than 5 lines
      let lineCount = 1;

      // Extract the text content to count lines
      const extractText = (node: any): string => {
        if (typeof node === "string") return node;
        if (node?.props?.children) {
          if (Array.isArray(node.props.children)) {
            return node.props.children.map(extractText).join("");
          }

          return extractText(node.props.children);
        }

        return "";
      };

      const codeContent = extractText(children);

      lineCount = codeContent.split("\n").length;

      // Only add line numbers class if more than 5 lines
      const classes = cn(
        "mdx-code-block",
        lineCount > MAX_LINES_FOR_LINE_NUMBERS ? "docs-code-block-line-numbers" : undefined,
        props.className,
      );

      return (
        <CodeBlock {...props} className={classes}>
          <Pre>{children}</Pre>
        </CodeBlock>
      );
    },
    ...components,
  };
}

