      page.locator('.view-lines').getByText(challengeSolution)
    ).not.toBeVisible();
    await expect(
      page.getByText(translations.buttons['go-to-next'])
    ).not.toBeVisible();
    await expect(
      page.getByText(translations.learn['tests-completed'])
    ).not.toBeVisible();

