import { registerDecorator, ValidationOptions, ValidationArguments } from 'class-validator';

export function MainTextMaxLength(maxLength: number, validationOptions?: ValidationOptions) {
  return function (object: Object, propertyName: string) {
    registerDecorator({
      name: 'mainTextMaxLength',
      target: object.constructor,
      propertyName: propertyName,
      constraints: [maxLength],
      options: validationOptions,
      validator: {
        validate(value: any, args: ValidationArguments) {
          if (typeof value !== 'string') {
            return false;
          }
          return value.length <= maxLength;
        },
        defaultMessage(args: ValidationArguments) {
          return `Main text must not exceed ${maxLength} characters`;
        },
      },
    });
  };
}

function createSelector<T, U>(
  inputSelectors: ((state: T) => any)[],
  transform: (...args: any[]) => U
): (state: T) => U {
  const memo: Map<string, U> = new Map();

  return (state: T) => {
    const args = inputSelectors.map(selector => selector(state));
    const key = JSON.stringify(args);

    if (memo.has(key)) {
      return memo.get(key)!;
    }

    const result = transform(...args);
    memo.set(key, result);
    return result;
  };
}

