async function asyncZip<T>(arrays: Array<Promise<Array<T>>>): Promise<Array<Array<T>>> {
  const resolvedArrays = await Promise.all(arrays);
  const minLength = Math.min(...resolvedArrays.map(arr => arr.length));
  const zippedArray: Array<Array<T>> = [];

  for (let i = 0; i < minLength; i++) {
    const zippedElement: Array<T> = [];
    for (let j = 0; j < resolvedArrays.length; j++) {
      zippedElement.push(resolvedArrays[j][i]);
    }
    zippedArray.push(zippedElement);
  }

  return zippedArray;
}

