function loadModule(modulePath: string, moduleName: string, callback: () => void): void {
  const isSyncModule = (module: any) => module && typeof module === 'object' && module.__esModule
  const isAsyncModule = (module: any) => module && typeof module === 'function' && module.toString().includes('System.import')

  const loadSyncModule = () => {
    const module = require(modulePath)
    window[moduleName] = module
    callback()
  }

  const loadAsyncModule = () => {
    const importPromise = import(modulePath)
    importPromise.then((module: any) => {
      window[moduleName] = module
      callback()
    })
  }

  if (isSyncModule(require(modulePath))) {
    loadSyncModule()
  } else if (isAsyncModule(require(modulePath))) {
    loadAsyncModule()
  } else {
    throw new Error('Unsupported module format')
  }
}

