interface SignatureData {
  type: 'ECDSA' | 'Schnorr';
  publicKey: number;
  message: number;
  signature: number;
}

interface Secp256k1WASM {
  sign: (e: number) => void;
  signSchnorr: (e: number) => void;
  verify: (Q: number, strict: number) => number;
  verifySchnorr: () => number;
}

function verifySignature(secp256k1: Secp256k1WASM, signature: SignatureData): boolean {
  if (signature.type === 'ECDSA') {
    // Perform ECDSA signature verification
    secp256k1.sign(signature.message);
    const result = secp256k1.verify(signature.publicKey, signature.signature);
    return result === 1;
  } else if (signature.type === 'Schnorr') {
    // Perform Schnorr signature verification
    secp256k1.signSchnorr(signature.message);
    const result = secp256k1.verifySchnorr();
    return result === 1;
  } else {
    throw new Error('Invalid signature type');
  }
}

