async function calculateTotalBalance(accountIds: AccountId[], query: GetAccountBalanceQuery): Promise<MoneyEntity> {
  try {
    const balancePromises: Promise<MoneyEntity>[] = accountIds.map(accountId => query.getAccountBalance(accountId));
    const balances: MoneyEntity[] = await Promise.all(balancePromises);

    const totalBalance: MoneyEntity = balances.reduce((acc, curr) => {
      return { value: acc.value + curr.value };
    }, { value: 0 });

    return totalBalance;
  } catch (error) {
    throw new Error('Failed to calculate total balance: ' + error.message);
  }
}

