function calculateAverageSalary(employees: { name: string, salary: number }[]): number {
    let totalSalary = 0;
    let validEmployeeCount = 0;

    for (const employee of employees) {
        if (typeof employee.salary === 'number' && !isNaN(employee.salary)) {
            totalSalary += employee.salary;
            validEmployeeCount++;
