export interface PdResponse {
  status: number;
  data: any;
}

export class HttpManager {
  public async get(url: string): Promise<PdResponse> {
    return this.makeRequest({ url, method: PdMethod.GET });
  }

  public async post(url: string, data?: any): Promise<PdResponse> {
    return this.makeRequest({ url, method: PdMethod.POST, data });
  }

  public async put(url: string, data?: any): Promise<PdResponse> {
    return this.makeRequest({ url, method: PdMethod.PUT, data });
  }

  public async delete(url: string): Promise<PdResponse> {
    return this.makeRequest({ url, method: PdMethod.DELETE });
  }

  private async makeRequest(request: PdRequest): Promise<PdResponse> {
    try {
      const response = await fetch(request.url, {
        method: request.method,
        body: request.data ? JSON.stringify(request.data) : undefined,
        headers: {
          "Content-Type": "application/json",
        },
      });

      const responseData = await response.json();
      return { status: response.status, data: responseData };
    } catch (error) {
      throw new Error(`Failed to make ${request.method} request to ${request.url}: ${error.message}`);
    }
  }
}

