function requestAnimationFramePolyfill(process: () => void): number {
  let startTime = Date.now();
  let expectedTime = startTime + 16.67;
  let timeoutId: number;

  const loop = () => {
    const currentTime = Date.now();
    const elapsed = currentTime - startTime;

    if (currentTime < expectedTime) {
      timeoutId = setTimeout(loop, expectedTime - currentTime);
    } else {
      process();
      startTime = currentTime;
      expectedTime = startTime + 16.67;
      timeoutId = setTimeout(loop, 16.67 - (elapsed % 16.67));
    }
  };

  timeoutId = setTimeout(loop, 0);
  return timeoutId;
}

