    while ((match = this.expression.match(/^([*/])(\d+(\.\d+)?)/))) {
      this.expression = this.expression.slice(match[0].length);
      if (match[1] === "*") {
        result *= parseFloat(match[2]);
      } else {
        result /= parseFloat(match[2]);
      }
    }
    return result;
