import { Observable, Subscriber } from 'rxjs';

export class DateTimeModel extends Observable<Date> {
  public dateTime: Date;

  constructor() {
    super((subscriber: Subscriber<Date>) => {
      subscriber.next(this.dateTime);
    });
    this.dateTime = new Date();
  }

  updateDateTime(newDateTime: Date): void {
    this.dateTime = newDateTime;
    this.notifyObservers();
  }

  getFormattedDateTime(): string {
    const year = this.dateTime.getFullYear();
    const month = String(this.dateTime.getMonth() + 1).padStart(2, '0');
    const day = String(this.dateTime.getDate()).padStart(2, '0');
    const hours = String(this.dateTime.getHours()).padStart(2, '0');
    const minutes = String(this.dateTime.getMinutes()).padStart(2, '0');
    const seconds = String(this.dateTime.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
  }

  private notifyObservers(): void {
    this.forEach((subscriber) => {
      subscriber.next(this.dateTime);
    });
  }
}

function encryptPassword(password: string): string {
