function extractClassAsNamedExport(moduleContent: string, className: string): string {
    const exportRegex = /export\s*\*\s*from\s*\".*\";/;
    const classRegex = new RegExp(`(<any>globalObject)\\.${className}\\s*=\\s*${className};`, 'g');

    const modifiedContent = moduleContent.replace(classRegex, `$1.${className} = ${className};\n\nexport { ${className} } from "../index";`);

    if (exportRegex.test(modifiedContent)) {
        return modifiedContent.replace(exportRegex, `export { ${className} } from "../index";`);
    } else {
        return `${modifiedContent}\n\nexport { ${className} } from "../index";`;
    }
}

