function memoized(
  _prototype: unknown,
  propertyKey: string,
  descriptor: PropertyDescriptor,
): void {
  if (!descriptor.get) {
    throw new Error(`@memoized can only be applied to property getters!`);
  }
  if (descriptor.set) {
    throw new Error(`@memoized can only be applied to readonly properties!`);
  }

  const originalGetter = descriptor.get;
  const memoizationKey = Symbol(`${propertyKey}_memoized`);

  descriptor.get = function () {
    if (!this[memoizationKey]) {
      this[memoizationKey] = originalGetter.call(this);
    }
    return this[memoizationKey];
  };
}

