class ResourceManager<T> {
  private resources: T[] = [];

  destroy(resource: T): void {
    const index = this.resources.indexOf(resource);
    if (index !== -1) {
      this.resources.splice(index, 1);
    }
  }

  drain(): PromiseLike<undefined> {
    return new Promise((resolve) => {
      // Simulate asynchronous draining process
      setTimeout(() => {
        this.resources = [];
        resolve(undefined);
      }, 1000);
    });
  }

  clear(): PromiseLike<undefined[]> {
    return new Promise((resolve) => {
      // Simulate asynchronous clearing process
      setTimeout(() => {
        const clearedResources = this.resources.slice();
        this.resources = [];
        resolve(clearedResources);
      }, 1000);
    });
  }

  use<U>(cb: (resource: T) => U): PromiseLike<U> {
    return new Promise((resolve, reject) => {
      if (this.resources.length === 0) {
        reject(new Error("No resources available"));
      } else {
        // Simulate asynchronous resource usage
        setTimeout(() => {
          const result = cb(this.resources[0]);
          resolve(result);
        }, 500);
      }
    });
  }
}

