import * as bs58 from 'bs58';

class Wallet {
  address: string;
  publicKeyB64: string;
  privateKey: Buffer;

  constructor(address: string, publicKeyB64: string, privateKey: Buffer) {
    this.address = address;
    this.publicKeyB64 = publicKeyB64;
    this.privateKey = privateKey;
  }
}

function generateDesmosWallet(mnemonic: string): Wallet {
  const seed = bip39.mnemonicToSeedSync(mnemonic);
  const node = bip32.fromSeed(seed);
  const child = node.derivePath("m/44'/852'/0'/0/0");
  const privateKey = child.privateKey;
  const publicKey = secp256k1.publicKeyCreate(privateKey, false);
  const address = generateDesmosAddress(publicKey);

  return new Wallet(address, publicKey.toString('base64'), privateKey);
}

function generateDesmosAddress(publicKey: Buffer): string {
  const hash = Buffer.from('desmos', 'utf8');
  const publicKeyHash = Buffer.from(secp256k1.hash160(publicKey));
  const payload = Buffer.concat([hash, publicKeyHash]);
  const checksum = Buffer.from(secp256k1.hash256(payload)).slice(0, 4);
  const addressBytes = Buffer.concat([payload, checksum]);
  return bs58.encode(addressBytes);
}

