  topPadding: number = 0;
  itemHeight: number = 50;
  viewportHeight: number = 300;
  itemsPerViewport: number;

  @ViewChild('viewport') viewport: ElementRef;

  ngAfterViewInit() {
    this.itemsPerViewport = Math.ceil(this.viewportHeight / this.itemHeight);
    this.updateVisibleItems();
  }

  onScroll(event: Event) {
    this.updateVisibleItems();
  }

  updateVisibleItems() {
    const scrollTop = this.viewport.nativeElement.scrollTop;
    const startIndex = Math.floor(scrollTop / this.itemHeight);
    const endIndex = Math.min(startIndex + this.itemsPerViewport, this.items.length);
    this.visibleItems = this.items.slice(startIndex, endIndex);
    this.topPadding = startIndex * this.itemHeight;
    if (endIndex === this.items.length) {
      this.fetchMore.emit(endIndex);
    }
  }
}

