import { ItemFunc, AsyncGeneratorFunc } from './types';

export function mapProp<T, U extends T>(prop: string, func: ItemFunc<T, U>): AsyncGeneratorFunc<T, U> {
  return async function* (inputGenerator: AsyncGenerator<T, void, unknown>) {
    for await (const item of inputGenerator) {
      if (prop in item) {
        const transformedItem = { ...item, [prop]: func(item[prop]) };
        yield transformedItem as U;
      } else {
        yield item as U;
      }
    }
  };
}

