function findMatches(templateMatcher: TemplateMatcher): [number, number][] {
  const { haystack, needle, confidence, searchMultipleScales } = templateMatcher;
  const matches: [number, number][] = [];

  // Perform template matching algorithm to find matches
  // Pseudocode for template matching algorithm:
  // for each position (i, j) in haystack image {
  //   calculate similarity score between needle and haystack sub-image at (i, j)
  //   if similarity score > confidence {
  //     add (i, j) to matches
  //   }
  // }

  // Example implementation using nested loops (assuming grayscale images)
  for (let i = 0; i <= haystack.height - needle.height; i++) {
    for (let j = 0; j <= haystack.width - needle.width; j++) {
      let similarityScore = calculateSimilarity(haystack, needle, i, j);
      if (similarityScore > confidence) {
        matches.push([j, i]); // Note the order of j and i for column-major indexing
      }
    }
  }

  return matches;
}

function calculateSimilarity(haystack: Image, needle: Image, offsetX: number, offsetY: number): number {
  let sum = 0;
  for (let i = 0; i < needle.height; i++) {
    for (let j = 0; j < needle.width; j++) {
      sum += (haystack[offsetY + i][offsetX + j] - needle[i][j]) ** 2;
