class StyleApplicator {
  private styleRules: Record<string, string>;

  constructor(styleRules: Record<string, string>) {
    this.styleRules = styleRules;
  }

  applyStyles(element: HTMLElement): void {
    for (const [style, value] of Object.entries(this.styleRules)) {
      element.style[style] = value;
    }
  }

  getAppliedStyles(element: HTMLElement): Record<string, string> {
    const appliedStyles: Record<string, string> = {};
    const computedStyles = window.getComputedStyle(element);
    for (const style in this.styleRules) {
      appliedStyles[style] = computedStyles.getPropertyValue(style);
    }
    return appliedStyles;
  }
}

export default StyleApplicator;

