import { Injectable } from '@nestjs/common';

@Injectable()
export class FindService {
  constructor() {}

  findValue(head: Node | null, value: number): number {
    let index = 0;
    let current = head;
    while (current !== null) {
      if (current.value === value) {
        return index;
      }
      current = current.next;
      index++;
    }
    return -1;
  }
}

