interface IVector2 {
  v: number[];
  length(): number;
}

type TypedArrayConstructor = Int8ArrayConstructor | Uint8ArrayConstructor | Int16ArrayConstructor | Uint16ArrayConstructor | Int32ArrayConstructor | Uint32ArrayConstructor | Float32ArrayConstructor | Float64ArrayConstructor;

class Vector2 {
  static _normalize(vec: IVector2, type: TypedArrayConstructor): number[] {
    const length = vec.length();
    return this._divide(vec, length, type);
  }

  static _add(l_vec: IVector2, r_vec: IVector2, type: TypedArrayConstructor): number[] {
    const result = [];
    for (let i = 0; i < l_vec.v.length; i++) {
      result.push(l_vec.v[i] + r_vec.v[i]);
    }
    return new type(result);
  }

  static _subtract(l_vec: IVector2, r_vec: IVector2, type: TypedArrayConstructor): number[] {
    const result = [];
    for (let i = 0; i < l_vec.v.length; i++) {
      result.push(l_vec.v[i] - r_vec.v[i]);
    }
    return new type(result);
  }

  private static _divide(vec: IVector2, length: number, type: TypedArrayConstructor): number[] {
    const result = [];
    for (let i = 0; i < vec.v.length; i++) {
      result.push(vec.v[i] / length);
    }
    return new type(result);
  }
