function ApiProperty(metadata: { required: boolean }) {
  return function (target: any, propertyKey: string) {
    // Implementation of ApiProperty decorator
  };
}

function validateProperties<T extends { new (...args: any[]): {} }>(constructor: T) {
  const requiredProperties: string[] = [];

  for (const propertyKey of Object.getOwnPropertyNames(constructor.prototype)) {
    const propertyMetadata = Reflect.getMetadata('apiProperty', constructor.prototype, propertyKey);
    if (propertyMetadata && propertyMetadata.required) {
      requiredProperties.push(propertyKey);
    }
  }

  const originalConstructor = constructor;

  function newConstructor(...args: any[]) {
    for (const prop of requiredProperties) {
      if (!(prop in this)) {
        throw new Error(`Missing required property: ${prop}`);
      }
    }
    return new originalConstructor(...args);
  }

  newConstructor.prototype = originalConstructor.prototype;

  return newConstructor as T;
}

