    days: number;
    hours: number;
    minutes: number;
    seconds: number;
    remain_seconds: number;
}
```
The `DateCountDown` interface represents the countdown values, including the remaining time in days, hours, minutes, seconds, and total remaining seconds.

Your `CountDown` class should have the following properties and methods:
- `timeRemaining`: A number representing the remaining time in seconds.
- `onComplete`: An optional callback function that should be executed when the countdown completes.

You need to implement the logic to calculate the countdown values and update them at regular intervals until the time runs out. The countdown values should be updated every second.

Your task is to complete the `CountDown` class to achieve the desired functionality.

code:
export interface DateCountDown {
    days: number;
    hours: number;
    minutes: number;
    seconds: number;
    remain_seconds: number;
}

export class CountDown {
    timeRemaining: number;
    onComplete?: Function;

    constructor(timeRemaining: number, onComplete?: Function) {
        this.timeRemaining = timeRemaining;
        this.onComplete = onComplete;
        this.startCountdown();
    }

    private startCountdown(): void {
        const intervalId = setInterval(() => {
            this.timeRemaining--;
            if (this.timeRemaining < 0) {
                clearInterval(intervalId);
                if (this.onComplete) {
                    this.onComplete();
                }
            }
        }, 1000);
    }

    private calculateCountdownValues(): DateCountDown {
        const secondsInMinute = 60;
        const secondsInHour = 60 * secondsInMinute;
        const secondsInDay = 24 * secondsInHour;

        const days = Math.floor(this.timeRemaining / secondsInDay);
        const remainSecondsAfterDays = this.timeRemaining % secondsInDay;
        const hours = Math.floor(remainSecondsAfterDays / secondsInHour);
        const remainSecondsAfterHours = remainSecondsAfterDays % secondsInHour;
        const minutes = Math.floor(remainSecondsAfterHours / secondsInMinute);
        const seconds = remainSecondsAfterHours % secondsInMinute;

        return {
            days,
            hours,
            minutes,
            seconds,
            remain_seconds: this.timeRemaining
        };
    }
}

