function flattenObject(object: { [key: string]: any }, prefix: string = ''): { [key: string]: any } {
  let flatten: { [key: string]: any } = {}
  for (const key in object) {
    const value = object[key]
    if (typeof value === 'object' && value !== null) {
      const nestedFlatten = flattenObject(value, `${prefix}${key}.`)
      flatten = { ...flatten, ...nestedFlatten }
    } else {
      flatten[`${prefix}${key}`] = value
    }
  }
  return flatten
