import { connect, NatsConnection, createInbox } from "nats";
import { JetStreamManager, StreamAPI } from "nats";

async function interactWithJetstreamManager(
  serverConfig: any,
  streamName: string,
  streamConfig: any
): Promise<string[]> {
  const nc = await connect(serverConfig); // Connect to the NATS server
  const jsm = await nc.jetstreamManager(); // Initialize the Jetstream Manager

  // Create a new stream with the given name and configuration
  await jsm.streams.add(streamName, streamConfig);

  // Retrieve the list of streams and return their names
  const streams = await jsm.streams.list().next();
  const streamNames = streams.map((stream: StreamAPI) => stream.config.name);

  // Delete the stream with the given name
  await jsm.streams.delete(streamName);

  // Close the NATS connection
  await nc.close();

  return streamNames;
}

