code:
function registerTaggedCallbacks(
  taggedCallbacks: TaggedCallback[]
): (() => void)[] {
  const unregisterFunctions: (() => void)[] = [];
  for (const taggedCallback of taggedCallbacks) {
    const unregisterFunction = () => {
      ipc.removeRenderer(taggedCallback.tag, taggedCallback.callback);
    };
    ipc.answerRenderer(taggedCallback.tag, taggedCallback.callback);
    unregisterFunctions.push(unregisterFunction);
  }
  return unregisterFunctions;
}

