interface IUrlParams {
  [key: string]: string | number | boolean;
}

function appendUrlParam({ paramName, url, paramValue }: { paramName: string; url: string; paramValue: string | number | boolean }): string {
  const separator = url.includes('?') ? '&' : '?';
  return `${url}${separator}${encodeURIComponent(paramName)}=${encodeURIComponent(paramValue.toString())}`;
}

function constructURL({ url, params = {} }: { url: string; params?: IUrlParams }): string {
  const validParams = Object.entries(params)
    .filter(([, paramValue]) => !!paramValue)
    .map(([paramName, paramValue]) => appendUrlParam({ paramName, url, paramValue }));

  return validParams.length > 0 ? validParams.reduce((acc, param) => acc + param, url) : url;
}

