code:
export default function useIntersection({
  threshold = defaultThreshold,
}: IUseIntersectionInput = {}): IUseIntersection {
  const [targetNode, setTargetNode] = React.useState<Element | null>(null)
  const [isIntersected, setIntersected] = React.useState(false)
  const [intersectionRate, setIntersectionRate] = React.useState(0)

  React.useEffect(() => {
    if (!targetNode) return

    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[0]
        if (entry.isIntersecting) {
          setIntersected(true)
          setIntersectionRate(entry.intersectionRatio)
        } else {
          setIntersected(false)
          setIntersectionRate(0)
        }
      },
      { threshold }
    )

    observer.observe(targetNode)

    return () => {
      observer.disconnect()
    }
  }, [targetNode, threshold])

  const handleSetTargetNode = (node: Element | null) => {
    if (node) {
      setTargetNode(node)
    }
  }

  return {
    isIntersected,
    intersectionRate,
    setTargetNode: handleSetTargetNode,
  }
}

