import Color from 'color';

function calculateAverageColor(colorLevels: ColorLevelsObject): Color {
  const colorValues = Object.values(colorLevels);
  const totalRed = colorValues.reduce((acc, color) => acc + color.red(), 0);
  const totalGreen = colorValues.reduce((acc, color) => acc + color.green(), 0);
  const totalBlue = colorValues.reduce((acc, color) => acc + color.blue(), 0);

  const averageRed = totalRed / colorValues.length;
  const averageGreen = totalGreen / colorValues.length;
  const averageBlue = totalBlue / colorValues.length;

  return Color.rgb(averageRed, averageGreen, averageBlue);
}

