function extractInterfaceProperties(interfaceCode: string): string[] {
    const propertyRegex = /(?:\s{2,}|\t{1,})(\w+):/g;
    const matches = interfaceCode.match(propertyRegex);
    if (matches) {
        return matches.map(match => match.trim().replace(/:/, ''));
    }
    return [];
}

