function evenFibonacciSum(limit: number): number {
    let sum = 0;
    let prev = 1;
    let curr = 1;

    while (curr <= limit) {
        if (curr % 2 === 0) {
            sum += curr;
        }
        let next = prev + curr;
        prev = curr;
        curr = next;
    }

    return sum;
}

