code:
function getActivePlayerId(url: string): string | null {
  if (url === "/") {
    return null;
  } else {
    const urlSegments = url.split("/");
    const idSegment = urlSegments[urlSegments.length - 1];
    const id = idSegment.match(/\d+/); // Extract numeric ID from the segment
    return id ? id[0] : null;
  }
}

