export interface INotMatchingResolvedRoute {
  state: 'not-matching';
}

function categorizeRoutes(routes: INotMatchingResolvedRoute[]): { matching: number, notMatching: number } {
  let matchingCount = 0;
  let notMatchingCount = 0;

  for (const route of routes) {
    if (route.state === 'not-matching') {
