function parseEquipmentPacket(packet: DataBuffer): { entity: number, equipment: { pos: number, item: Item }[] } {
    const entity = packet.readVarInt();
    const equipment = [];

    while (packet.bytesAvailable() > 0) {
        const posByte = packet.readByte();
        const pos = posByte & 0x7F; // Extract the position from the byte
        const isLast = (posByte & 0x80) !== 0; // Check if it's the last equipment item

        const item = packet.readItem(); // Read the equipment item

        equipment.push({ pos, item });

        if (isLast) {
            break; // If it's the last item, exit the loop
        }
    }

    return { entity, equipment };
}

