import { Injectable } from '@angular/core';
import { Http, Response, Headers, RequestOptions } from '@angular/http';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/operator/map';
import 'rxjs/add/operator/catch';
import 'rxjs/add/observable/throw';

@Injectable()
export class HttpService {
  private base_url: string = 'https://example.com/api/';

  constructor(private _http: Http) { }

  private getHeaders(): RequestOptions {
    return new RequestOptions({ headers: new Headers({ 'Content-Type': 'application/json' }) });
  }

  public post(side: string, id: number): Observable<any> {
    return this._http.post(this.base_url + side + '/' + id, null, this.getHeaders())
      .map((response: Response) => response.json())
      .catch(this.handleError);
  }

  private handleError(error: Response): Observable<any> {
    let errorMessage: string;
    if (error.json().error) {
      errorMessage = error.json().error;
    } else {
      errorMessage = 'Server error';
    }
    console.error(errorMessage);
    return Observable.throw(errorMessage);
  }
}

