// Implementation of @CustomSelector decorator
export function CustomSelector(): MethodDecorator {
    return function (target: any, propertyKey: string, descriptor: PropertyDescriptor) {
        const originalMethod = descriptor.value;

        descriptor.value = function (...args: any[]) {
            return originalMethod.apply(this, args);
        };

        const computedKey = `__${NGXS_COMPUTED_OPTION}__${propertyKey}`;
        Object.defineProperty(target, computedKey, {
            value: descriptor.value,
            enumerable: true,
            configurable: true,
            writable: true
        });

        return descriptor;
    };
}

