code:
export class PaginationService {
  public pages: Array<number> = [];
  public currentPage: number;
  public numOfPages: number;

  constructor() {}

  generatePages(currentPage: number, numOfPages: number): Array<number> {
    this.currentPage = currentPage;
    this.numOfPages = numOfPages;

    const maxPagesToShow = 5;
    const middlePage = Math.ceil(maxPagesToShow / 2);
    let startPage = Math.max(1, currentPage - middlePage + 1);
    let endPage = Math.min(startPage + maxPagesToShow - 1, numOfPages);

    if (endPage - startPage + 1 < maxPagesToShow) {
      startPage = Math.max(1, endPage - maxPagesToShow + 1);
    }

    this.pages = Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i);
    return this.pages;
  }

  onPageChanged(pageNumber: number): void {
    if (pageNumber >= 1 && pageNumber <= this.numOfPages) {
      this.pageChanged.emit(pageNumber);
    }
  }
}

