import * as ts from 'typescript';
import * as fs from 'fs';

function extractImportedComponents(filePath: string): string[] {
  const fileContent = fs.readFileSync(filePath, 'utf8');
  const sourceFile = ts.createSourceFile(filePath, fileContent, ts.ScriptTarget.Latest, true);

  const importedComponents: string[] = [];

  ts.forEachChild(sourceFile, (node) => {
    if (ts.isImportDeclaration(node)) {
      if (node.importClause) {
        if (node.importClause.namedBindings && ts.isNamedImports(node.importClause.namedBindings)) {
          node.importClause.namedBindings.elements.forEach((element) => {
            importedComponents.push(element.name.text);
          });
        } else if (node.importClause.name && ts.isIdentifier(node.importClause.name)) {
          importedComponents.push(node.importClause.name.text);
        }
      }
    }
  });

  return Array.from(new Set(importedComponents));
}

