code:
function extractAngularComponents(input: string): string[] {
  const componentRegex = /export class (\w+) implements/g;
  const importRegex = /import { (\w+) } from ['"]([^'"]+)['"]/g;
  let components: string[] = [];
  let matches: RegExpExecArray | null;

  while ((matches = componentRegex.exec(input)) !== null) {
    components.push(matches[1]);
  }

  let imports: string[] = [];
  while ((matches = importRegex.exec(input)) !== null) {
    imports.push(matches[1]);
  }

  return components.concat(imports);
}

