/// Emits one semantic agent event into the app's append-only agent
    /// journal and blocks until the app acknowledges the durable commit.
    ///
    /// This is the structured replacement for the fire-and-forget
    /// `set_agent_lifecycle` verb: sidebar lifecycle is now a reduction over
    /// these events. Attribution is decided by the caller — an event that
    /// could not be attributed carries `unattributedReason` (and no target)
    /// so the app surfaces it as a diagnostic instead of guessing a pane.
    ///
    /// Delivery failures are never silent: they land in the dead-letter file
    /// and, when a session store and telemetry are provided, in the throttled
    /// hook-failure report channel.
    func emitAgentJournalEvent(
        client: SocketClient,
        kind: AgentJournalEventKind,
        source: String,
        agentKey: String,
        sessionId: String?,
        workspaceId: String?,
        surfaceId: String?,
        unattributedReason: String? = nil,
        isSubagent: Bool = false,
        pendingWork: Bool = false,
        nativeEvent: String?,
        declaredPhase: AgentLifecyclePhase? = nil,
        detail: String? = nil,
        store: ClaudeHookSessionStore? = nil,
        telemetry: CLISocketSentryTelemetry? = nil
    ) {
        // A malformed or partial target (empty string, non-UUID, missing
        // half) is never trusted: the event is journaled as an explicit
        // diagnostic instead of being rejected at admission or guessed.
        let validWorkspaceId = workspaceId.flatMap { UUID(uuidString: $0) != nil ? $0 : nil }
        let validSurfaceId = surfaceId.flatMap { UUID(uuidString: $0) != nil ? $0 : nil }
        let hasCompleteTarget = validWorkspaceId != nil && validSurfaceId != nil
        let resolvedReason: String?
        if let unattributedReason {
            resolvedReason = unattributedReason
        } else if !hasCompleteTarget {
            resolvedReason = "malformed-target"
        } else {
            resolvedReason = nil
        }
        let draft = AgentJournalEventDraft(
            kind: kind,
            occurredAtMs: Int64(Date().timeIntervalSince1970 * 1000),
            source: source,
            agentKey: agentKey,
            sessionId: sessionId,
            workspaceId: resolvedReason == nil ? validWorkspaceId : nil,
            surfaceId: resolvedReason == nil ? validSurfaceId : nil,
            unattributedReason: resolvedReason,
            isSubagent: isSubagent,
            pendingWork: pendingWork,
            nativeEvent: nativeEvent,
            declaredPhase: declaredPhase,
            detail: detail
        )
        if let problem = draft.validationProblem() {
            recordAgentJournalDeliveryFailure(
                draft: draft,
                message: "invalid draft: \(problem)",
                store: store,
                telemetry: telemetry
            )
            return
        }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        guard let data = try? encoder.encode(draft),
              let json = String(data: data, encoding: .utf8) else {
            recordAgentJournalDeliveryFailure(
                draft: draft,
                message: "encode failed",
                store: store,
                telemetry: telemetry
            )
            return
        }
        do {
            let response = try sendV1Command("agent_journal_append \(json)", client: client)
            guard response.hasPrefix("OK") else {
                recordAgentJournalDeliveryFailure(
                    draft: draft,
                    message: response,
                    store: store,
                    telemetry: telemetry
                )
                return
            }
        } catch {
            recordAgentJournalDeliveryFailure(
                draft: draft,
                message: String(describing: error),
                store: store,
                telemetry: telemetry
            )
        }
    }

/// Records a failed journal emission: appended to the bounded dead-letter
    /// file, warned on stderr, and (when possible) reported through the
    /// throttled hook-failure channel. Never silent.
    func recordAgentJournalDeliveryFailure(
        draft: AgentJournalEventDraft,
        message: String,
        store: ClaudeHookSessionStore?,
        telemetry: CLISocketSentryTelemetry?
    ) {
        appendAgentJournalDeadLetter(draft: draft, message: message)
        cliWriteStderr("Warning: agent journal append failed (\(draft.kind.rawValue)): \(message)\n")
        if let store, let telemetry {
            reportAgentHookFailure(
                stage: .journalAppend,
                agentName: draft.source,
                sessionId: draft.sessionId ?? "",
                event: draft.nativeEvent ?? draft.kind.rawValue,
                error: nil,
                store: store,
                telemetry: telemetry
            )
        }
    }

func throttleDecision(
        snapshot: AutoNamingSessionSnapshot,
        transcriptLineCount: Int,
        now: Date
    ) -> AutoNamingThrottleDecision {
        guard transcriptLineCount >= config.minTranscriptLines else {
            return .skipShortTranscript
        }
        let nowInterval = now.timeIntervalSince1970
        if let inFlightAt = snapshot.inFlightAt, nowInterval - inFlightAt < config.inFlightExpiry {
            return .skipInFlight
        }
        guard let lastLineCount = snapshot.lastLineCount, snapshot.lastNamedAt != nil else {
            // First naming for this session always qualifies; this also seeds
            // the baseline for resumed sessions arriving with a large
            // pre-existing transcript. A failed pass records only lastAttemptAt
            // (not lastNamedAt), so honor the cooldown here too — otherwise a
            // persistently failing summarizer respawns on every turn end.
            if let lastAttemptAt =

/// Resolves which agent should actually run the summarization for one
    /// naming pass, honoring the user's `automation.autoNamingAgent` override
    /// (carried on the socket probe response as `summarizer_agent`).
    ///
    /// `auto` / the session's own agent / an unsupported or uninstalled choice
    /// all collapse to `sessionAgent`, so naming never breaks. When a supported
    /// override is selected but its binary is missing, the chosen agent is
    /// returned as `missingOverride` so the caller can surface a Settings note.
    func resolvedSummarizerAgent(
        probe: [String: Any],
        sessionAgent: String,
        env: [String: String],
        telemetry: CLISocketSentryTelemetry
    ) -> (agent: String, missingOverride: String?) {
        // Pure decision (unit-tested in CmuxSettings); the CLI only supplies the
        // binary-availability probe and emits telemetry.
        let decision = AutoNamingAgentCatalog.resolveSummarizer(
            chosen: probe["summarizer_agent"] as? String,
            sessionAgent: sessionAgent,
            isInstalled: { summarizerBinaryAvailable(agent: $0, env: env) }
        )
        if let missing = decision.missingOverride {
            telemetry.breadcrumb("auto-name.summarizer-fallback.\(missing)")
        } else if decision.agent != sessionAgent {
            telemetry.breadcrumb("auto-name.summarizer-override.\(decision.agent)")
        }
        return (decision.agent, decision.missingOverride)
    }

/// Best-effort report of a naming problem to the app so it can surface a
    /// message in Settings. Never touches the workspace/tab title; if the socket
    /// call fails, naming simply stays silent.
    func reportAutoNamingProblem(
        _ category: String,
        agent: String,
        workspaceId: String,
        client: SocketClient
    ) {
        _ = try? client.sendV2(method: "workspace.set_auto_title", params: [
            "failure": category,
            "agent": agent,
            "workspace_id": workspaceId
        ])
    }

func autoNamingMessages(
        for def: AgentHookDef,
        parsedInput: ClaudeHookParsedInput,
        client: SocketClient,
        workspaceId: String,
        engine: AutoNamingEngine = AutoNamingEngine()
    ) -> [AutoNamingTranscriptMessage] {
        guard usesHookMessageCacheForAutoNaming(def),
              let object = parsedInput.rawObject ?? parsedInput.object else {
            return []
        }
        guard let probe = try? client.sendV2(
            method: "workspace.set_auto_title",
            params: ["probe": true, "workspace_id": workspaceId]
