/// Returns a cheap monotonic progress metric for file-backed transcripts.
    /// File size preserves growth and compaction/shrink signals without
    /// streaming the whole transcript on every naming pass.
    func textFileGrowthMetric(path: String, fallbackLineCount: Int) -> Int {
        let expandedPath = NSString(string: path).expandingTildeInPath
        guard let attributes = try? FileManager.default.attributesOfItem(atPath: expandedPath),
              let size = attributes[.size] as? NSNumber else {
            return fallbackLineCount
        }
        return max(fallbackLineCount, size.intValue / 128)
    }

/// Runs the summarizer subprocess with the prompt on stdin and a hard
    /// deadline, returning captured stdout (nil on failure, timeout, or
    /// non-zero exit).
    func runAutoNamingSummarizer(
        executable: String,
        arguments: [String],
        prompt: String,
        environment: [String: String],
        timeout: TimeInterval
    ) -> String? {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: executable)
        process.arguments = arguments
        process.environment = environment

let exited = (try? waitForProcessExit(process, timeout: timeout)) ?? false
        if !exited {
            process.terminate()
            if ((try? waitForProcessExit(process, timeout: 2)) ?? false) == false {
                kill(process.processIdentifier, SIGKILL)
                _ = try? waitForProcessExit(process, timeout: 1)
            }
            return nil
        }
        try? stdoutHandle.close()
        guard process.terminationStatus == 0,
              let output = try? Data(contentsOf: outputURL) else {
            return nil
        }
        return String(data: output, encoding: .utf8)
    }

/// Validates viewport CLI arguments and builds the `browser.viewport.set` parameters.
    static func browserViewportSetParams(
        _ arguments: [String],
        surfaceID: String
    ) throws -> [String: Any] {
        if arguments.first?.lowercased() == "reset" {
            guard arguments.count == 1 else {
                throw CLIError(
                    message: String(
                        localized: "cli.browser.error.viewportResetAdditionalArguments",
                        defaultValue: "browser viewport reset does not accept additional arguments"
                    )
                )
            }
            return ["surface_id": surfaceID, "reset": true]
        }

guard arguments.count == 2,
              let width = Int(arguments[0]),
              let height = Int(arguments[1]) else {
            throw CLIError(
                message: String(
                    localized: "cli.browser.error.viewportRequiresSizeOrReset",
                    defaultValue: "browser viewport requires: <width> <height> | reset"
                )
            )
        }
        return ["surface_id": surfaceID, "width": width, "height": height]
    }

private static func nonEmptyCampfireEnvironmentValue(_ name: String, in environment: [String: String]) -> String? {
        let trimmed = environment[name]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return trimmed.isEmpty ? nil : trimmed
    }

private func existingCampfireExtensionContents(at url: URL, fileManager: FileManager = .default) throws -> String {
        guard fileManager.fileExists(atPath: url.path) else { return "" }
        do {
            return try String(contentsOf: url, encoding: .utf8)
        } catch {
            let message = String.localizedStringWithFormat(
                String(
                    localized: "cli.hooks.campfire.error.readFailed",
                    defaultValue: "Failed to read %@"
                ),
                url.path
            )
            throw CLIError(message: message)
        }
    }

func installCampfireExtensionHooks(_ _: AgentHookDef) throws {
        let extensionURL = campfireExtensionURL()
        let fileManager = FileManager.default
        let skipConfirm = ProcessInfo.processInfo.arguments.contains("--yes")
            || ProcessInfo.processInfo.arguments.contains("-y")
        let existing = try existingCampfireExtensionContents(at: extensionURL, fileManager: fileManager)
        if existing == Self.campfireExtensionSource {
            print(String.localizedStringWithFormat(
                String(
                    localized: "cli.hooks.campfire.alreadyUpToDate",
                    defaultValue: "Campfire hooks already up to date at %@"
                ),
                extensionURL.path
            ))
            return
        }
        if !existing.isEmpty, !existing.contains(Self.campfireExtensionMarker) {
            throw CLIError(message: String.localizedStringWithFormat(
                String(
                    localized: "cli.hooks.campfire.error.notCmuxExtension",
                    defaultValue: "%@ exists and is not a cmux extension; leaving it alone"
                ),
                extensionURL.path
            ))
        }
        if !skipConfirm {
            Self.printInstallPreview(
                path: extensionURL.path,
                oldContent: existing,
                newContent: Self.campfireExtensionSource,
                fallbackContent: Self.campfireExtensionSource
            )
            print(String(localized: "cli.hooks.campfire.confirmProceed", defaultValue: "\nProceed? [y/N] "), terminator: "")
            guard readLine()?.lowercased().hasPrefix("y") == true else {
                print(String(localized: "cli.hooks.campfire.aborted", defaultValue: "Aborted."))
                return
            }
        }
        try fileManager.createDirectory(
            at: extensionURL.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        try Self.campfireExtensionSource.write(to: extensionURL, atomically: true, encoding: .utf8)
        print(String.localizedStringWithFormat(
            String(
                localized: "cli.hooks.campfire.installed",
                defaultValue: "Campfire hooks installed at %@"
            ),
            extensionURL.path
        ))
    }

func uninstallCampfireExtensionHooks(_ _: AgentHookDef) throws {
        let extensionURL = campfireExtensionURL()
        let fm = FileManager.default
        guard fm.fileExists(atPath: extensionURL.path) else {
            print(String.localizedStringWithFormat(
                String(
                    localized: "cli.hooks.campfire.noneFound",
                    defaultValue: "No Campfire cmux extension found at %@"
                ),
                extensionURL.path
            ))
            return
        }
        let existing = try existingCampfireExtensionContents(at: extensionURL, fileManager: fm)
        guard existing.contains(Self.campfireExtensionMarker) else {
            print(String.localizedStringWithFormat(
                String(
                    localized: "cli.hooks.campfire.refuseRemoveMissingMarker",
                    defaultValue: "Refusing to remove %@: missing cmux marker"
                ),
                extensionURL.path
            ))
            return
        }
        try fm.removeItem(at: extensionURL)
        print(String.localizedStringWithFormat(
            String(
                localized: "cli.hooks.campfire.removed",
                defaultValue: "Removed Campfire cmux extension from %@"
            ),
            extensionURL.path
        ))
    }

/// Resolve `raw` to a workspace id only when that workspace currently exists.
    func strictClaudeHookWorkspaceId(_ raw: String, client: SocketClient) -> String? {
        // UUID identities (hook session records, live CMUX_WORKSPACE_ID) validate directly.
        if isUUID(raw) {
            return claudeHookWorkspaceExists(raw, client: client) ? raw : nil
        }
        // Explicit non-UUID selectors (handle refs like "workspace:1", numeric indexes —
        // both documented for --workspace) resolve strictly. `resolveWorkspaceId` fails
        // closed for every non-blank selector, and `raw` is non-blank here (callers pass
        // it through `nonEmptyClaudeHookIdentifier`), so the focused-tab fallback inside
        // `resolveWorkspaceId` is structurally unreachable and the "never fall back to
        // focused" invariant holds.
        guard let resolved = try? resolveWorkspaceId(raw, client: client),
              isUUID(resolved),
              claudeHookWorkspaceExists(resolved, client: client) else {
            return nil
        }
        return resolved
    }

func claudeHookWorkspaceExists(_ workspaceId: String, client: SocketClient) -> Bool {
        (try? client.sendV2(method: "surface.list", params: ["workspace_id": workspaceId])) != nil
    }

/// Caller-TTY binding that refuses ambiguous TTY matches: returns a binding only
    /// when every `debug.terminals` entry for the caller's TTY name agrees on a single
    /// workspace and surface (macOS reuses `ttysNNN` names, and stale entries can
    /// shadow live ones).
    /// PID-derived bindings don't need this guard — a PID lives in exactly one surface.
    func uniqueCallerTerminalBindingByTTY(
        client: SocketClient,
        includeAmbientTTY: Bool = true
    ) -> CallerTerminalBinding? {
        guard let ttyName = resolveCallerTTYName(includeAmbientTTY: includeAmbientTTY) else {
            return nil
        }
        return uniqueCallerTerminalBindingByTTY(ttyName: ttyName, client: client)
    }

func runClaudePushNotificationHook(
        client: SocketClient,
        telemetry: CLISocketSentryTelemetry,
        parsedInput: ClaudeHookParsedInput,
        sessionStore: ClaudeHookSessionStore,
        routing: ClaudeHookRoutingContext,
        markFeedTelemetryHandled: () -> Void,
        sendFeedTelemetry: (String?, String?) -> Void
    ) throws {
        telemetry.breadcrumb("claude-hook.push-notification")
        // PostToolUse bridge for Claude Code's PushNotification tool. The
        // tool delivers through a raw OSC desktop notification, and cmux
        // deliberately drops raw OSC notifications from surfaces running a
        // hook-integrated agent (they would duplicate hook notifications),
        // so without this bridge every PushNotification is silently
        // swallowed inside cmux. The tool's own Notification hook never
        // fires for it. Mirror the tool's delivery decision: bridge exactly
        // when the tool reports its terminal notification as sent
        // (tool_response.localSent); fail open when an older client omits
        // the structured response.
        guard let pushMessage = claudePushNotificationMessage(parsedInput.rawObject) else {
            telemetry.breadcrumb("claude-hook.push-notification.empty")
            printClaudeHookAck()
            return
        }
        guard claudePushNotificationShouldBridge(parsedInput.rawObject) else {
            telemetry.breadcrumb("claude-hook.push-notification.skipped")
            printClaudeHookAck()
            return
        }
        let mappedSession = parsedInput.sessionId.flatMap { try? sessionStore.lookup(sessionId: $0) }
        guard let resolvedTarget = try resolveClaudeHookDeliveryTarget(
            mappedSession: mappedSession,
            routing: routing,
            client: client
        ) else {
            markFeedTelemetryHandled()
            telemetry.breadcrumb("claude-hook.push-notification.unresolved")
            printClaudeHookAck()
            return
        }
        let workspaceId = resolvedTarget.workspaceId
        let resolvedSurface = resolvedTarget
        let surfaceId = resolvedSurface.surfaceId
        sendFeedTelemetry(workspaceId, surfaceId)
        guard shouldApplyClaudeHookVisibleMutation(
            sessionStore: sessionStore,
            parsedInput: parsedInput,
            workspaceId: workspaceId,
            surfaceId: resolvedSurface.isAuthoritative ? surfaceId : nil,
            telemetry: telemetry
        ) else {
            telemetry.breadcrumb("claude-hook.push-notification.stale")
            printClaudeHookAck()
            return
        }
        let claudePid = mappedSession?.pid ?? claudeAgentPID(from: ProcessInfo.processInfo.environment)
        guard !shouldSuppressNestedAgentVisibleMutations(
            currentAgentPID: claudePid,
            env: ProcessInfo.processInfo.environment
        ) else {
            telemetry.breadcrumb("claude-hook.push-notification.nested-suppressed")
            printClaudeHookAck()
            return
        }
        let title = String(
            localized: "cli.claude-hook.notification.title",
            defaultValue: "Claude Code"
        )
        // A model-initiated push is an ungated always-deliver alert (no
        // meta tag, like legacy untagged payloads). No lifecycle/status
        // change: the agent is usually still running when it fires, and a
        // push must not flip a running pane to "Needs input".
        let payload = notificationPayload(title: title, subtitle: "", body: pushMessage)
        _ = try sendV1Command("notify_target_async \(workspaceId) \(surfaceId) \(payload)", client: client)
        printClaudeHookAck()
    }

/// Message for a PushNotification PostToolUse payload: the tool input's
    /// `message`, falling back to the structured tool_response `message`.
    /// Read from rawObject: the compacted `object` allowlist does not keep
    /// `tool_input.message` or `tool_response`. Normalized and capped like
    /// every other hook notification body (240 chars, the message-key limit
    /// in claudeHookCompactFieldLimit) so a model-controlled push cannot grow
    /// the notification store/UI unboundedly.
    private func claudePushNotificationMessage(_ object: [String: Any]?) -> String? {
        guard let object else { return nil }
        let rawMessage: String?
        if let input = object["tool_input"] as? [String: Any],
           let message = firstString(in: input, keys: ["message"]) {
            rawMessage = message
        } else if let response = object["tool_response"] as? [String: Any],
                  let message = firstString(in: response, keys: ["message"]) {
            rawMessage = message
        } else {
            rawMessage = nil
        }
        guard let rawMessage else { return nil }
        let normalized = normalizedSingleLine(rawMessage)
        guard !normalized.isEmpty else { return nil }
        return truncate(normalized, maxLength: 240)
    }

/// The cmux-owned directory holding the generated codex hook scripts.
    /// `~/.cmux/hooks` (NOT the user's `~/.codex`), created on demand. Returns
    /// nil if it cannot be created, so the caller falls back to inline commands.
    static func codexHookScriptsDirectory() -> URL? {
        let home = FileManager.default.homeDirectoryForCurrentUser
        let dir = home
            .appendingPathComponent(".cmux", isDirectory: true)
            .appendingPathComponent("hooks", isDirectory: true)
        do {
            try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
            return dir
        } catch {
            return nil
        }
    }

/// Writes (idempotently) a `#!/bin/sh` hook script for one event into `dir`
    /// and returns its absolute path, or nil on any failure. The body is the
    /// same env-driven fire-and-forget snippet used inline; as a real executable
    /// file it runs under any runtime, including ones that exec the hook command
    /// directly rather than through a shell. Content is identical across
    /// invocations, so the file is only rewritten when missing or changed.
    static func writeCodexHookScript(subcommand: String, body: String, in dir: URL) -> String? {
        let contents = "#!/bin/sh\n\(body)\n"
        guard let scriptName = CodexHookScriptName(
            contents: contents,
            subcommand: subcommand
        ) else {
            return nil
        }
        // Keep generated scripts immutable. Older cmux processes may still write
        // the legacy path while newer Codex sessions reference this content ID.
        let url = dir.appendingPathComponent(
            scriptName.filename,
            isDirectory: false
        )
        let fileManager = FileManager.default
        if let existing = try? String(contentsOf: url, encoding: .utf8), existing == contents {
            // Ensure it stays executable, then reuse.
            try? fileManager.setAttributes([.posixPermissions: 0o755], ofItemAtPath: url.path)
            return url.path
        }
        do {
            try contents.data(using: .utf8)?.write(to: url, options: .atomic)
            try fileManager.setAttributes([.posixPermissions: 0o755], ofItemAtPath: url.path)
            return url.path
        } catch {
            return nil
        }
    }

/// Verifies a hook checkpoint before the standalone CLI publishes it.
    ///
    /// Hook publication is intentionally decided in this short-lived CLI
    /// process, not on cmux's MainActor or socket worker. The verifier starts
    /// with one indexed SQLite lookup and applies hard byte, line, and fallback
    /// candidate limits to the legacy rollout path, so the bounded inspection
    /// cannot turn an app UI/socket lane into a history loader.
    func codexResumeBindingVerification(
        sessionId: String,
        transcriptPath: String?,
        launchCommand: AgentHookLaunchCommandRecord?
    ) -> CodexSessionResumeVerification {
        let environment = ProcessInfo.processInfo.environment
        let codexHome = codexResumeBindingEffectiveHome(
            launchEnvironment: launchCommand?.environment,
            launchVerificationHome: launchCommand?.verificationHome,
            ambientEnvironment: environment
        )
        return CodexSessionResumeVerifier().verify(
            sessionId: sessionId,
            transcriptPath: transcriptPath,
            codexHome: codexHome
        )
    }

func codexResumeBindingEffectiveHome(
        launchEnvironment: [String: String]?,
        launchVerificationHome: String? = nil,
        ambientEnvironment: [String: String] = ProcessInfo.processInfo.environment
    ) -> String {
        if let launchHome = normalizedHookValue(launchEnvironment?["CODEX_HOME"]) {
            return (launchHome as NSString).expandingTildeInPath
        }
        if let launchHome = normalizedHookValue(launchVerificationHome)
            ?? normalizedHookValue(launchEnvironment?["HOME"]) {
            return URL(fileURLWithPath: (launchHome as NSString).expandingTildeInPath, isDirectory: true)
                .appendingPathComponent(".codex", isDirectory: true)
                .path
        }
        if let ambientHome = normalizedHookValue(ambientEnvironment["CODEX_HOME"]) {
            return (ambientHome as NSString).expandingTildeInPath
        }
        let home = normalizedHookValue(ambientEnvironment["HOME"]) ?? NSHomeDirectory()
        return URL(fileURLWithPath: home, isDirectory: true)
            .appendingPathComponent(".codex", isDirectory: true)
            .path
    }

